"""Plain-language terms; build.py adds links and writes static glossary HTML."""
TERMS = [
 ('vector','Vector','An ordered list of numbers of fixed length, read as a point or an arrow in a space with that many dimensions. An activation is a vector.'),
 ('activation','Activation','The vector a model component outputs for one token at one layer; here a row of the residual stream after block 6 of GPT-2 small, length 768.'),
 ('residual-stream','Residual stream','The running vector each transformer layer reads from and adds to; the sum of the embedding and every earlier layer output.'),
 ('scalar','Scalar','A single number, as opposed to a vector or matrix.'),
 ('linear-combination','Linear combination','A sum of vectors each multiplied by a scalar, such as 2u − 3v.'),
 ('dot-product','Dot product','The sum of the products of matching coordinates of two vectors; a scalar that grows with alignment and with length.'),
 ('norm','Norm','The length of a vector: the square root of its dot product with itself.'),
 ('unit-vector','Unit vector','A vector of norm 1; any nonzero vector divided by its norm.'),
 ('cosine-similarity','Cosine similarity','The dot product of two vectors divided by the product of their norms; the cosine of the angle between them, between −1 and 1.'),
 ('direction','Direction','A unit vector, or any nonzero vector read only for its orientation; a feature direction is a candidate axis along which activations are measured.'),
 ('projection','Projection','The component of a vector along a direction; its coefficient is the dot product with the unit direction, a scalar per token.'),
 ('residual','Residual','What is left of a vector after its projection is subtracted; orthogonal to the direction.'),
 ('orthogonal','Orthogonal','Two vectors with dot product zero; at right angles.'),
 ('orthonormal','Orthonormal','A set of unit vectors that are pairwise orthogonal.'),
 ('matrix','Matrix','A rectangular grid of numbers with a shape (rows, columns); read as a linear map, a batch of row vectors, or a table.'),
 ('linear-map','Linear map','A function that respects addition and scaling: f(u + v) = f(u) + f(v) and f(cu) = c f(u). Every matrix defines one and every linear map between coordinate spaces is a matrix.'),
 ('shape','Shape','The tuple of array dimensions, such as (302, 768); the type signature of a tensor.'),
 ('matrix-multiplication','Matrix multiplication','Combining an (n, k) and a (k, m) matrix into an (n, m) matrix whose entries are dot products of rows with columns; composition of linear maps.'),
 ('transpose','Transpose','The matrix with rows and columns swapped, written Aᵀ.'),
 ('einsum','einsum','A notation naming each axis by a letter, so that repeated letters are summed over; makes the shape of a product explicit.'),
 ('basis','Basis','A set of vectors such that every vector in the space is exactly one linear combination of them; coordinates are the coefficients.'),
 ('neuron-basis','Neuron basis','The standard basis in which coordinate i is the i-th entry of the activation; one basis among many, with no special status in the residual stream.'),
 ('change-of-basis','Change of basis','Rewriting the same vector in the coordinates of a different basis; for an orthonormal basis the new coordinates are dot products.'),
 ('span','Span','All linear combinations of a set of vectors; a line, plane, or higher flat through the origin.'),
 ('linear-independence','Linear independence','No vector in the set is a linear combination of the others; equivalently the only combination giving zero has all-zero coefficients.'),
 ('rank','Rank','The number of linearly independent columns (equivalently rows) of a matrix; the dimension of the space it maps onto.'),
 ('subspace','Subspace','A flat through the origin closed under addition and scaling; the span of some vectors.'),
 ('superposition','Superposition','A representation holding more features than it has dimensions, with feature directions that are not all orthogonal; defined in Toy Models of Superposition.'),
 ('gram-schmidt','Gram–Schmidt','A procedure that turns a list of vectors into an orthonormal list with the same span, by subtracting projections in order.'),
 ('least-squares','Least squares','Choosing coefficients to minimise the sum of squared differences between predictions and targets.'),
 ('normal-equations','Normal equations','XᵀX w = Xᵀy: the condition that the least-squares residual is orthogonal to every column of X.'),
 ('linear-probe','Linear probe','A direction and offset fitted to predict a label from activations; its projection is the probe score.'),
 ('ridge','Ridge','Least squares with a penalty on the squared norm of the coefficients; shrinks the solution and makes it unique when there are more columns than rows.'),
 ('held-out','Held-out','Data not used to fit a direction, kept for checking what the direction predicts.'),
 ('eigenvector','Eigenvector','A nonzero vector that a square matrix only scales: A v = λ v.'),
 ('eigenvalue','Eigenvalue','The scale factor λ attached to an eigenvector.'),
 ('symmetric-matrix','Symmetric matrix','A square matrix equal to its transpose; its eigenvectors can be chosen orthonormal and its eigenvalues are real.'),
 ('covariance-matrix','Covariance matrix','The (d, d) matrix of covariances between pairs of coordinates across the rows; its diagonal holds variances.'),
 ('variance','Variance','The average squared deviation from the mean; along a unit direction, the variance of the projection coefficients.'),
 ('pca','PCA','Principal component analysis: the orthonormal directions of greatest variance in a centred data matrix, which are the eigenvectors of its covariance.'),
 ('principal-component','Principal component','One of the PCA directions, ordered by variance explained.'),
 ('variance-explained','Variance explained','The fraction of total variance lying along a component; the component’s eigenvalue divided by the sum of all eigenvalues.'),
 ('scree-plot','Scree plot','Variance explained plotted against component number, used to see how quickly the components stop mattering.'),
 ('svd','SVD','Singular value decomposition: A = U Σ Vᵀ with orthonormal U and V and non-negative singular values in Σ, for any matrix.'),
 ('singular-value','Singular value','A diagonal entry of Σ: how much the matrix stretches along the matching right singular vector.'),
 ('low-rank-approximation','Low-rank approximation','Keeping only the k largest singular triples; the best rank-k approximation in the least-squares sense.'),
 ('gradient','Gradient','The vector of partial derivatives of a scalar function; the direction of steepest increase.'),
 ('gradient-ascent','Gradient ascent','Repeatedly stepping along the gradient to increase a scalar function.'),
 ('correlation','Correlation','The cosine similarity of two centred sequences; between −1 and 1, zero when unrelated in the linear sense.'),
 ('permutation-test','Permutation test','Recomputing a statistic many times with the labels shuffled, to see what values arise when there is no relation.'),
 ('baseline','Baseline','A comparison that would also score well if the claim were empty, such as a random direction or shuffled labels.'),
 ('centering','Centering','Subtracting the mean row from every row, so that the data have mean zero before PCA or covariance.'),
 ('outer-product','Outer product','The (n, m) matrix u vᵀ formed from an n-vector and an m-vector; every rank-one matrix is one.'),
 ('identity-matrix','Identity matrix','The square matrix I with ones on the diagonal; the map that changes nothing.'),
 ('attention-head-weights','Attention head weights','For one head, the matrices W_Q, W_K, W_V of shape (d_model, d_head) and W_O of shape (d_head, d_model); the products W_Q W_Kᵀ and W_V W_O have rank at most d_head.'),
]
GLOSSARY = {slug:dict(name=name, short=definition, defn=definition) for slug,name,definition in TERMS}
